using System;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Non-modal tutorial dock: only its speech bubble receives raycasts. The game and navigation stay usable.
 public sealed class MiraCoach:MonoBehaviour {
  public Image Portrait;public Text Speaker,Speech,Error;public InputField Name;public Button Confirm,Next,Skip,Target;public RectTransform Panel;
  GameState observed;GameRuntime game;string signature,full="";int offset;bool De=>game.State.Settings.language=="de";
  public void Initialize(GameRuntime runtime){game=runtime;MiraMotion.Attach(Portrait,game);Confirm.onClick.AddListener(()=>{var check=NameRules.Validate(Name.text,NameBalance.AIMaximum);if(!check.Ok){Error.gameObject.SetActive(true);Error.text=De?"Bitte einen gültigen Namen wählen.":"Please choose a valid name.";Portrait.GetComponent<MiraMotion>().Cue="warning";return;}Act("name",Name.text);});Next.onClick.AddListener(()=>{if(offset<full.Length){Page();return;}Act("continue");});Skip.onClick.AddListener(()=>Act(game.State.Story.open==null?"skip-tutorial":"skip"));Target.onClick.AddListener(()=>{var q=TutorialNavigation.Quote(game.State);if(q!=null)game.NavigateTo(q.Tab,q.Element,q.Mode);});foreach(var text in GetComponentsInChildren<Text>(true))if(text.GetComponent<UiLocalizedText>()==null)text.gameObject.AddComponent<UiLocalizedText>().Initialize(game);Refresh();}
  void Act(string op,string value=""){Portrait.GetComponent<MiraMotion>().Cue="explain";game.Act(s=>NarrativeBridge.Action(s,op,value));signature=null;Refresh();}
  void Update(){if(game!=null)Refresh();}
  void LateUpdate(){if(game!=null)Resize();}
  void Page(){int end=Math.Min(full.Length,offset+100);if(end<full.Length&&full.Length-end<25)end=full.Length;if(end<full.Length){int sentence=full.LastIndexOf('.',end-1,end-offset);int split=full.LastIndexOf(' ',end,end-offset);if(sentence>offset+20)end=sentence+1;else if(split>offset)end=split;}Speech.text=full.Substring(offset,end-offset).Trim();offset=end;while(offset<full.Length&&full[offset]==' ')offset++;Next.gameObject.SetActive(!string.IsNullOrEmpty(game.State.Retention.aiName)&&(game.State.Story.open!=null||offset<full.Length));Next.GetComponentInChildren<Text>().text=De?"Weiter":"Continue";Resize();}
  void Resize(){bool naming=string.IsNullOrEmpty(game.State.Retention.aiName);var height=GetComponent<LayoutElement>();float desired=naming?Mathf.Max(210,Mathf.Ceil(Speech.preferredHeight)+138):Mathf.Clamp(Mathf.Ceil(Speech.preferredHeight)+96,148,232);if(height.preferredHeight!=desired)height.minHeight=height.preferredHeight=desired;var offset=new Vector2(84,naming?122:58);if(Speech.rectTransform.offsetMin!=offset)Speech.rectTransform.offsetMin=offset;}
  void Refresh(){var s=game.State;if(ReferenceEquals(observed,s))return;observed=s;string key=s.Story.open+"|"+s.Story.target+"|"+s.Story.tutorial+"|"+s.Settings.language+"|"+s.Retention.aiName;if(key==signature)return;signature=key;bool naming=string.IsNullOrEmpty(s.Retention.aiName),dialog=s.Story.open!=null;Speaker.text="Dr. Mira Voss";Name.gameObject.SetActive(naming);Confirm.gameObject.SetActive(naming);Next.gameObject.SetActive(!naming&&dialog);Skip.gameObject.SetActive(true);Target.gameObject.SetActive(!naming&&!dialog);Error.text="";Error.gameObject.SetActive(false);Confirm.GetComponentInChildren<Text>().text=De?"Bestätigen":"Confirm";Skip.GetComponentInChildren<Text>().text=De?"Überspringen":"Skip";Target.GetComponentInChildren<Text>().text=De?"Ziel zeigen":"Show target";full=naming?UiLocalizedText.Translate("Wie soll deine KI heißen?",s.Settings.language):dialog?NarrativeBridge.Text(s,s.Story.open):(TutorialNavigation.Quote(s)?.Explanation??"");// The current Unity surface consumes discrete taps; do not promise the TS-only hold repeater.
   if(s.Story.open=="tutorial-tap"||!dialog&&s.Story.target=="tap")full=full.Replace(" oder halte gedrückt für mehrere Impulse","").Replace(" or hold down for repeated impulses","").Replace(" Halte gedrückt für mehrere Impulse.","").Replace(" Hold down for repeated impulses.","");offset=0;Page();}
 }
}
